def longest_consecutive(nums: list[int]) -> int:
    if not nums:
        return 0

    nums_set = set(nums)
    longest = 0

    for num in nums_set:
        if num - 1 not in nums_set:
            current_num = num
            current_length = 1

            while current_num + 1 in nums_set:
                current_num += 1
                current_length += 1

            longest = max(longest, current_length)

    return longest
```

