def longest_valid_parentheses(s: str) -> int:
    stack = []
    max_length = 0
    current_length = 0
    for char in s:
        if char == '(':
            stack.append(char)
            current_length += 1
        elif char == ')':
            if stack:
                stack.pop()
                current_length += 1
                if not stack:
                    max_length = max(max_length, current_length)
            else:
                current_length = 0
    return max_length
