def longest_valid_parentheses(s: str) -> int:
    stack = []
    max_length = 0
    current_length = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if not stack:
                continue
            stack.pop()
            if not stack:
                current_length = i + 1
            else:
                current_length = i - stack[-1]
            max_length = max(max_length, current_length)

    return max_length
```

