def word_break(s: str, word_dict: list[str]) -> bool:
    def dfs(i):
        if i == len(s):
            return True
        for word in word_dict:
            if s[i:i+len(word)] == word and dfs(i+len(word)):
                return True
        return False

    return dfs(0)
```

